-- 156: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_156_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_156_guard;
INSERT INTO _migration_156_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_026' AND NOT (q.topic_id IS 'topic_was_electronics_b002_6' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What feedback condition is required to sustain sinusoidal oscillation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Loop gain greater than unity with 180° net phase shift","B. Loop gain magnitude of unity with total phase shift of 0° or 360°","C. Loop gain below unity with 360° net phase shift","D. Zero feedback at the selected frequency"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The Barkhausen condition requires reinforcing feedback of the correct phase and a loop-gain magnitude that sustains rather than grows or decays. Therefore the correct answer is B: Loop gain magnitude of unity with total phase shift of 0° or 360°.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_026' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_156_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_027' AND NOT (q.topic_id IS 'topic_was_electronics_b002_6' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which oscillator commonly uses a crystal for high frequency stability?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An RC phase-shift oscillator","B. A Hartley oscillator","C. A crystal-controlled oscillator","D. An astable multivibrator"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Quartz has a high-Q mechanical resonance that provides a stable frequency-selective element in the feedback network. Therefore the correct answer is C: A crystal-controlled oscillator.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_027' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_156_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_028' AND NOT (q.topic_id IS 'topic_was_electronics_b002_6' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What waveform is produced directly by a relaxation oscillator that repeatedly charges and discharges a capacitor between thresholds?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A pure sinusoid from linear resonance","B. A constant DC level after one charge cycle","C. A single exponentially decaying pulse","D. A non-sinusoidal periodic waveform such as a square or sawtooth wave"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Threshold switching and capacitor ramps create repeating abrupt transitions or ramps rather than a pure sinusoid. Therefore the correct answer is D: A non-sinusoidal periodic waveform such as a square or sawtooth wave.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_028' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_156_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_029' AND NOT (q.topic_id IS 'topic_was_electronics_b002_6' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of an oscillator in a radio transmitter?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Generate a periodic carrier or reference signal","B. Select and recover the incoming information signal","C. Remove modulation from the transmitted carrier","D. Hold the transmitter supply at a fixed DC voltage"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Transmitters require a stable periodic signal that can be amplified, multiplied or modulated to carry information. Therefore the correct answer is A: Generate a periodic carrier or reference signal.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_029' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_156_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_030' AND NOT (q.topic_id IS 'topic_was_electronics_b002_6' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why does excessive positive feedback make a linear amplifier unstable?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It always reduces loop gain below unity","B. It can cause the circuit to generate unwanted sustained oscillations","C. It guarantees a wider bandwidth without phase effects","D. It shifts the bias point but cannot create an AC output"]' AND q.correct_answer IS 'B' AND q.explanation IS 'If loop magnitude and phase meet oscillation conditions unintentionally, disturbances are reinforced rather than damped. Therefore the correct answer is B: It can cause the circuit to generate unwanted sustained oscillations.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_030' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
